import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:techpie/features/campus_card/data/crypto/sm2_offline_crypto.dart';

void main() {
  test('band JS SM2 signatures verify with Sm2OfflineCrypto.verify', () {
    // Fixture generated by the band implementation (vela_app/src/common/sm2.js)
    // via its QR pipeline; regenerate when the JS side changes intentionally.
    final raw = jsonDecode(
      File('test/fixtures/vela-sm2.json').readAsStringSync(),
    ) as Map<String, dynamic>;
    final cases = (raw['cases'] as List).cast<Map<String, dynamic>>();
    expect(cases.length, 8);
    final crypto = Sm2OfflineCrypto();
    for (final c in cases) {
      final messageHex = c['message'] as String;
      final message = <int>[
        for (var i = 0; i < messageHex.length; i += 2)
          int.parse(messageHex.substring(i, i + 2), radix: 16),
      ];
      expect(
        crypto.verify(
          publicKeyXHex: c['publicKeyXHex'] as String,
          publicKeyYHex: c['publicKeyYHex'] as String,
          message: message,
          signatureHex: c['signatureHex'] as String,
        ),
        isTrue,
        reason: 'band signature must stay valid: $c',
      );
    }
  });
}
